    constructor(formId) {
        this.form = document.getElementById(formId);
        this.fields = {
            fullName: document.getElementById('fullName'),
            email: document.getElementById('email'),
            phone: document.getElementById('phone')
        };
        this.successMessage = document.getElementById('successMessage');
        this.touchedFields = new Set();

        this.init();
    }

    init() {
        // Add blur listeners to track touched fields
        Object.entries(this.fields).forEach(([key, field]) => {
            if (field) {
                field.addEventListener('blur', () => this.markFieldTouched(key));
                field.addEventListener('input', () => this.validateField(key));
            }
        });

        // Add form submit listener
        this.form.addEventListener('submit', (e) => this.handleSubmit(e));
    }

    markFieldTouched(fieldName) {
        this.touchedFields.add(fieldName);
        this.validateField(fieldName);
    }

    validateField(fieldName) {
        if (!this.touchedFields.has(fieldName)) {
            this.clearFieldError(fieldName);
            return true;
        }

        const field = this.fields[fieldName];
        const errorSpan = document.querySelector(`[data-field="${fieldName}"]`);
        let isValid = true;
        let errorMessage = '';

        if (fieldName === 'fullName') {
            if (!field.value.trim()) {
                isValid = false;
                errorMessage = 'Full name is required';
            } else if (field.value.trim().length < 2) {
                isValid = false;
                errorMessage = 'Full name must be at least 2 characters';
            }
        }

        if (fieldName === 'email') {
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!field.value.trim()) {
                isValid = false;
                errorMessage = 'Email address is required';
            } else if (!emailRegex.test(field.value)) {
                isValid = false;
                errorMessage = 'Please enter a valid email address';
            }
        }

        if (fieldName === 'phone') {
            if (field.value.trim()) {
                const phoneRegex = /^\+?1?\s?\(?\d{3}\)?[\s.-]?\d{3}[\s.-]?\d{4}$/;
                if (!phoneRegex.test(field.value)) {
                    isValid = false;
                    errorMessage = 'Please enter a valid phone number';
                }
            }
        }

        if (isValid) {
            this.clearFieldError(fieldName);
        } else {
            this.showFieldError(fieldName, errorMessage);
        }

        return isValid;
    }

    showFieldError(fieldName, message) {
        const errorSpan = document.querySelector(`[data-field="${fieldName}"]`);
        if (errorSpan) {
            errorSpan.textContent = message;
        }
    }

    clearFieldError(fieldName) {
        const errorSpan = document.querySelector(`[data-field="${fieldName}"]`);
        if (errorSpan) {
            errorSpan.textContent = '';
        }
    }

    validateForm() {
        let isValid = true;

        // Mark required fields as touched and validate
        this.markFieldTouched('fullName');
        this.markFieldTouched('email');

        // Validate phone if touched
        if (this.touchedFields.has('phone')) {
            this.markFieldTouched('phone');
        }

        // Check all required fields
        if (!this.validateField('fullName')) {
            isValid = false;
        }
        if (!this.validateField('email')) {
            isValid = false;
        }
        if (this.fields.phone.value.trim() && !this.validateField('phone')) {
            isValid = false;
        }

        return isValid;
    }

    handleSubmit(e) {
        e.preventDefault();

        if (!this.validateForm()) {
            return;
        }

        // Show success message
        this.form.style.display = 'none';
        this.successMessage.style.display = 'block';

        // Reset form after a delay for demo purposes
        setTimeout(() => {
            this.resetForm();
        }, 3000);
    }

    resetForm() {
        this.form.reset();
        this.form.style.display = 'block';
        this.successMessage.style.display = 'none';
        this.touchedFields.clear();
        Object.keys(this.fields).forEach(key => this.clearFieldError(key));
    }
}

// Initialize form when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
    new ContactForm('contactForm');
});
